import analysis as a
_cells=None
def init():
 global _cells
 _cells=a.cells(a.json.loads((a.R/'MASKED-v3.1.json').read_text()))
def work(job):
 ci,key,si,scene,t=job;vv=_cells[key];seed=3100000+ci*100000+si*1000+t
 y=a.e.synthetic(vv,'null_low' if scene=='availability_only' else scene,seed)
 if key.startswith('B-') and scene=='availability_only':y=y*a.np.array([v['available'] for v in vv])
 rr=a.e.exact(vv,y);alpha=.05/(3 if key.startswith('A-') else 2)
 return dict(cell=key,scenario=scene,trial=t,seed=seed,p=rr['p'],degenerate=rr['degenerate'],flag=rr['p'] is not None and rr['p']<=alpha,outcome_sha256=a.hashlib.sha256(y.astype(a.np.uint8).tobytes()).hexdigest())
def main():
 a.check_seals();path=a.R/'SYNTHETIC-TRIALS-v3.1.jsonl';records=[a.json.loads(s) for s in path.read_text().splitlines()];done={(r['cell'],r['scenario'],r['trial']) for r in records};assert len(done)==len(records)
 init();keys=list(_cells);supp=a.json.loads((a.R/'SUPPORT-v3.1.json').read_text());jobs=[(ci,k,si,s,t) for ci,k in enumerate(keys) if supp[k]['gate'] for si,s in enumerate(a.SCENES) for t in range(200) if (k,s,t) not in done]
 for r in records[::max(1,len(records)//12)]:
  job=(keys.index(r['cell']),r['cell'],a.SCENES.index(r['scenario']),r['scenario'],r['trial']);assert work(job)==r
 a.save('RESUME-v3.1.json',dict(reason='New user message interrupted the running tool session; process session disappeared. Preserve completed trials and run only missing fixed-seed jobs.',completed=len(records),remaining=len(jobs),completed_file_sha256=a.sha(path),optimization='Cache immutable masked cells once per process instead of reparsing JSON on every trial. Exact original worker arithmetic, seeds, flags and outcome hashes verified on 12+ retained trials before resume.',BQ1_control_roles='Original attempt C five scenarios gate B-Q1. Availability-only was additionally generated by v3.1 code; retain as extra diagnostic outside the original B-Q1 null gates. This corrects an implementation scope error before outcomes; Part A retains all six required gates.'))
 a.seal('resume_frozen',['RESUME-v3.1.json','resume.py'])
 with a.ProcessPoolExecutor(max_workers=3,initializer=init) as pool,path.open('a') as f:
  for rr in pool.map(work,jobs,chunksize=10):
   records.append(rr);f.write(a.json.dumps(rr)+'\n');f.flush()
   if len(records)%200==0:print('Controls',len(records),'/9600',flush=True)
 summary={}
 for key in keys:
  controls=[]
  for s in a.SCENES:
   rr=[r for r in records if r['cell']==key and r['scenario']==s]
   if not rr:continue
   n=len(rr);flags=sum(r['flag'] for r in rr);ci=a.e.wilson(flags,n);role='power' if s=='positive' else 'extra_diagnostic' if key.startswith('B-') and s=='availability_only' else 'null';gate=ci[0]>=.8 if role=='power' else ci[1]<=.05 if role=='null' else None
   controls.append(dict(scenario=s,role=role,n=n,flags=flags,wilson95=ci,gate=gate,degenerate=sum(r['degenerate'] for r in rr)))
  null=bool(controls) and all(c['gate'] for c in controls if c['role']=='null');power=bool(controls) and all(c['gate'] for c in controls if c['role']=='power')
  summary[key]=dict(status='NOT ESTIMABLE' if not supp[key]['gate'] else 'FAIL NULL QUALIFICATION' if not null else 'UNDERPOWERED' if not power else 'QUALIFIED',null_pass=null,power_pass=power,controls=controls)
 a.save('QUALIFICATION-A-Q1.json',summary);a.seal('A_Q1_qualification_frozen',['QUALIFICATION-A-Q1.json','SYNTHETIC-TRIALS-v3.1.jsonl']);print(a.json.dumps({k:v['status'] for k,v in summary.items()}),flush=True)
if __name__=='__main__':main()
